#[test]
#[ignore]
fn measured_staged_copy() {
    for (name, files, size) in [("small-files", 200, 16 * 1024), ("large-files", 4, 8 * 1024 * 1024)] {
        let root = tempdir().unwrap();
        let source = root.path().join("source");
        fs::create_dir(&source).unwrap();
        for i in 0..files { fs::write(source.join(format!("file-{i}")), vec![42_u8; size]).unwrap(); }
        let mut samples = Vec::new();
        for iteration in 0..6 {
            let start = std::time::Instant::now();
            let inventory = inspect_source_tree(&source).unwrap();
            let destination = root.path().join(format!("copy-{iteration}"));
            copy_directory_staged(&inventory,&destination,&root.path().join(format!("stage-{iteration}")),1024 * 1024,|_,_|Ok(()),||Ok(()),||false).unwrap();
            if iteration > 0 { samples.push(start.elapsed().as_secs_f64() * 1000.0); }
            fs::remove_dir_all(destination).unwrap();
        }
        println!("COPY_BENCH {}", serde_json::json!({"scenario":name,"files":files,"fileBytes":size,"milliseconds":samples}));
    }
}
